sections.content:
.container {
  display: flex;

  /* Main axis direction */
  flex-direction: row;           /* row | row-reverse | column | column-reverse */

  /* Wrapping */
  flex-wrap: wrap;               /* nowrap | wrap | wrap-reverse */

  /* Main axis distribution */
  justify-content: space-between; /* flex-start | flex-end | center | space-around | space-evenly */

  /* Cross axis alignment */
  align-items: center;           /* flex-start | flex-end | center | stretch | baseline */

  /* Gap between items (modern, no more margin hacks) */
  gap: 16px;
  /* Or: row-gap: 16px; column-gap: 24px; */
}

.item {
  flex-grow: 1;    /* how much to grow relative to siblings */
  flex-shrink: 1;  /* how much to shrink when space is tight */
  flex-basis: 0%;  /* initial size before growing/shrinking */
}

/* Shorthand: flex: grow shrink basis */
.item { flex: 1; }          /* 1 1 0 — grow equally, shrink equally */
.item { flex: 0 0 200px; }  /* fixed 200px, no grow/shrink */
.item { flex: 2; }          /* grows twice as fast as flex: 1 siblings */

/* align-self: override align-items for a single item */
.special { align-self: flex-end; }

/* order: visual reordering without changing HTML */
.first { order: -1; }
.last  { order: 99; }

.grid {
  display: grid;

  /* 3 equal columns */
  grid-template-columns: 1fr 1fr 1fr;
  /* shorthand */
  grid-template-columns: repeat(3, 1fr);

  /* Explicit rows */
  grid-template-rows: 80px auto 60px;

  /* Gap */
  gap: 24px;
}

/* Responsive grid without media queries */
.auto-grid {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.header { grid-column: 1 / -1; }  /* span all columns */
.sidebar { grid-column: 1 / 2; grid-row: 2 / 4; }
.main    { grid-column: 2 / -1; }

/* Named areas for readable layouts */
.layout {
  grid-template-areas:
    'header header header'
    'sidebar main main'
    'footer footer footer';
}
.header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main    { grid-area: main; }
.footer  { grid-area: footer; }

/* Auto-placement: grid decides where items go */
.gallery {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: 200px;
  gap: 16px;
}

/* Dense packing fills gaps left by spanning items */
.masonry {
  grid-auto-flow: dense;
}

.wide-item {
  grid-column: span 2; /* spans 2 cols, auto-placed by grid */
}

/* Explicit vs implicit tracks */
.grid {
  grid-template-columns: repeat(3, 1fr); /* explicit columns */
  grid-auto-rows: minmax(100px, auto);   /* implicit row height */
}

/* Holy Grail Layout */
.page {
  display: grid;
  grid-template-areas:
    'header'
    'main'
    'sidebar'
    'footer';
  min-height: 100vh;
}

@media (min-width: 768px) {
  .page {
    grid-template-columns: 250px 1fr;
    grid-template-areas:
      'header  header'
      'sidebar main'
      'footer  footer';
  }
}

/* Card grid: responsive, no media queries */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 24px;
}

/* Centered content with max-width */
.container {
  width: min(1200px, 100% - 48px);
  margin-inline: auto;
}

/* Centered single element with flexbox */
.full-center {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}
